window.MD_KB_LOOKUP = (function () {
  const norm = s => String(s || '').toLowerCase().replace(/[’‘`]/g, "'").replace(/\s*\((md|mirror dungeon)\)\s*$/i, '').replace(/\s+/g, ' ').trim();
  const idx = {}; for (const [en, v] of Object.entries(window.MD_KB_GIFTS)) idx[norm(en)] = v;
  return en => idx[norm(en)] || null;
})();
// 中文名 → 英文名（找图片、找效果用）
window.MD_KB_EN = (function () { const m = {}; for (const [en, v] of Object.entries(window.MD_KB_GIFTS)) if (v.cn && !m[v.cn]) m[v.cn] = en; return m; })();
